nvidia-open-gpu-kernel-modules.setup:
for _kernel in ${kernels[@]}; do
    mkdir ${_kernel}
    bsdtar-static -xf %(sourcedir)/nvidia.tar.xz --strip-components=1 -C ${_kernel}

    pushd ${_kernel}
    # This is where patches would go
    # %patch %(pkgdir)/ibt-support.patch
    # Request by OGC: https://github.com/NVIDIA/open-gpu-kernel-modules/pull/1512
    [[ "${_kernel}" =~ "7.3" ]] && %patch %(pkgdir)/1512.patch
    popd
done
